import React, { useState, useEffect } from 'react';
import { MessageCircle, X, ShoppingBag, Star } from 'lucide-react';
import { productsData, getBestSellerProducts, getNewProducts, getDiscountedProducts } from '../../data/products';
import '../../styles/KirbyBot.css';

const KirbyBot = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isVisible, setIsVisible] = useState(true);
  const [recommendations, setRecommendations] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [currentMessage, setCurrentMessage] = useState("찾고있는 상품을 추천해드릴게요~ ⭐");

  // 실제 상품 데이터에서 추천 상품 생성
  const getRecommendationProducts = () => {
    const bestSellers = getBestSellerProducts();
    const newProducts = getNewProducts();
    const discountedProducts = getDiscountedProducts();

    // 다양한 추천 전략
    const strategies = [
      () => bestSellers.slice(0, 3), // 베스트셀러
      () => newProducts.slice(0, 3), // 신상품
      () => discountedProducts.slice(0, 3), // 할인상품
      () => productsData.filter(p => p.rating >= 4.5).slice(0, 3), // 높은 평점
      () => productsData.filter(p => p.stock <= 20).slice(0, 3), // 재고 부족 (긴급)
    ];

    // 랜덤 전략 선택
    const randomStrategy = strategies[Math.floor(Math.random() * strategies.length)];
    return randomStrategy();
  };

  // 랜덤 메시지 배열
  const botMessages = [
    "찾고있는 상품을 추천해드릴게요~ ⭐",
    "오늘의 특별 추천 상품을 보여드릴게요! ✨",
    "커비가 엄선한 상품들을 확인해보세요~ 🌟",
    "인기 상품들을 추천해드릴게요! 💫",
    "특가 상품들을 찾아왔어요~ 🎁",
    "베스트셀러 상품을 추천해드릴게요! 🏆",
    "새로 나온 상품들을 확인해보세요! 🆕",
    "높은 평점의 상품들을 추천해드릴게요! ⭐⭐⭐⭐⭐"
  ];

  // 랜덤 추천 상품 생성
  const generateRecommendations = () => {
    setIsLoading(true);

    // 랜덤 메시지 선택
    const randomMessage = botMessages[Math.floor(Math.random() * botMessages.length)];
    setCurrentMessage(randomMessage);

    // 1-3개의 랜덤 상품 선택
    const shuffled = [...sampleRecommendations].sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, Math.floor(Math.random() * 3) + 1);

    setTimeout(() => {
      setRecommendations(selected);
      setIsLoading(false);
    }, 800); // 로딩 시간을 조금 줄임
  };

  // 봇 클릭 시 자동으로 추천 갱신
  const handleBotClick = () => {
    if (!isOpen) {
      generateRecommendations();
    }
    toggleBot();
  };

  // 컴포넌트 마운트 시 추천 생성
  useEffect(() => {
    generateRecommendations();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // 추천 상품 클릭 핸들러
  const handleRecommendationClick = (product) => {
    // 상품 상세 페이지로 이동
    window.location.href = `/product/${product.id}`;
    // 클릭 후 말풍선 닫기
    setIsOpen(false);
  };

  // 봇 토글
  const toggleBot = () => {
    setIsOpen(!isOpen);
  };

  // 봇 다시 보이기 (3초 후)
  useEffect(() => {
    if (!isVisible) {
      const timer = setTimeout(() => {
        setIsVisible(true);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [isVisible]);

  if (!isVisible) return null;

  return (
    <div className="kirby-bot-container">
      {/* 말풍선 */}
      {isOpen && (
        <div className="kirby-bot-speech-bubble">
          <div className="speech-bubble-content">
            <div className="speech-bubble-header">
              <span className="bot-title">✨ 커비 추천봇 ✨</span>
              <button className="close-bot-btn" onClick={toggleBot}>
                <X size={16} />
              </button>
            </div>

            <div className="speech-bubble-message">
              <p>{currentMessage}</p>
            </div>

            {isLoading ? (
              <div className="loading-recommendations">
                <div className="loading-spinner"></div>
                <p>추천 상품을 찾고 있어요...</p>
              </div>
            ) : (
              <div className="recommendations-list">
                {recommendations.map((product) => (
                  <div 
                    key={product.id} 
                    className="recommendation-item"
                    onClick={() => handleRecommendationClick(product)}
                  >
                    <div className="recommendation-image">
                      <img src={product.image} alt={product.name} />
                      {product.discount > 0 && (
                        <div className="discount-badge">
                          -{product.discount}%
                        </div>
                      )}
                    </div>
                    <div className="recommendation-info">
                      <h4>{product.name}</h4>
                      <div className="recommendation-price">
                        {product.discount > 0 ? (
                          <>
                            <span className="original-price">
                              {product.price.toLocaleString()}원
                            </span>
                            <span className="discounted-price">
                              {Math.round(product.price * (1 - product.discount / 100)).toLocaleString()}원
                            </span>
                          </>
                        ) : (
                          <span className="price">
                            {product.price.toLocaleString()}원
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="recommendation-action">
                      <ShoppingBag size={16} />
                    </div>
                  </div>
                ))}
              </div>
            )}

            <div className="speech-bubble-footer">
              <button 
                className="refresh-btn"
                onClick={generateRecommendations}
                disabled={isLoading}
              >
                <Star size={14} />
                다른 추천 보기
              </button>
            </div>
          </div>

          {/* 말풍선 꼬리 */}
          <div className="speech-bubble-tail"></div>
        </div>
      )}

      {/* 커비봇 아이콘 */}
      <div className="kirby-bot-icon" onClick={handleBotClick}>
        <img 
          src="/bot/kirby-star2.png" 
          alt="커비봇" 
          className="kirby-image"
        />
        <div className="bot-pulse"></div>
        <div className="bot-notification">
          <MessageCircle size={12} />
        </div>
      </div>
    </div>
  );
};

export default KirbyBot;
